          st.sideHustle.type = "freelance";
          st.resources.cash += 600;
          st.resources.totalEarned = (st.resources.totalEarned || 0) + 600;
          if (st.skills.repair)
            st.skills.repair.xp = (st.skills.repair.xp || 0) + 30;
